       ['en' => 'CKD stage (by eGFR)', 'gu' => 'CKD સ્ટેજ (eGFR મુજબ)', 'f' => $EG . ' >= 90 ? T("G1 – સામાન્ય કે વધુ", "G1 – Normal or high") : (' . $EG . ' >= 60 ? T("G2 – થોડું ઘટેલું", "G2 – Mildly decreased") : (' . $EG . ' >= 45 ? T("G3a – હળવું-મધ્યમ ઘટેલું", "G3a – Mild to moderate") : (' . $EG . ' >= 30 ? T("G3b – મધ્યમ-ગંભીર ઘટેલું", "G3b – Moderate to severe") : (' . $EG . ' >= 15 ? T("G4 – ગંભીર ઘટેલું", "G4 – Severely decreased") : T("G5 – કિડની ફેલ્યોર", "G5 – Kidney failure")))))', 'fmt' => 'text'],
